// unsigned CDM16_fbb3: MUL_1..MUL_4, CLAx1-2 and CLAx3-4 without carry out
module cdm16_fbb3_u (
    input  wire [15:0] a,
    input  wire [15:0] b,
    output wire [31:0] p
);
    wire [7:0] al = a[7:0], ah = a[15:8], bl = b[7:0], bh = b[15:8];
    wire [15:0] r1;
    cdm16_fbb3_cdm8_aa u_m1 (.a(al), .b(bl), .p(r1));
    wire [15:0] r2;
    cdm16_fbb3_cdm8_a8 u_m2 (.a(ah), .b(bl), .p(r2));
    wire [15:0] r3;
    cdm16_fbb3_cdm8_a8 u_m3 (.a(al), .b(bh), .p(r3));
    wire [15:0] r4;
    cdm16_fbb3_cdm8_41 u_m4 (.a(ah), .b(bh), .p(r4));
    wire [7:0] s1 = r1[15:8] + r2[7:0] + r3[7:0];     // CLAx1-2, carry out dropped
    wire [7:0] s2 = r2[15:8] + r3[15:8] + r4[7:0];    // CLAx3-4, carry out dropped
    assign p = {r4[15:8], s2, s1, r1[7:0]};
endmodule

// signed CDM16_fbb3, sign-magnitude
module mul_core (
    input  wire signed [15:0] a,
    input  wire signed [15:0] b,
    output wire signed [31:0] p
);
    wire sa = a[15], sb = b[15];
    wire [15:0] am = {1'b0, a[14:0] ^ {15{sa}}};    // |a| = am + sa
    wire [15:0] bm = {1'b0, b[14:0] ^ {15{sb}}};
    wire [31:0] u;
    cdm16_fbb3_u u_core (.a(am), .b(bm), .p(u));
    wire [31:0] v = u + (sa ? {16'd0, bm} : 32'd0) + (sb ? {16'd0, am} : 32'd0) + (sa & sb);
    assign p = (sa ^ sb) ? -$signed(v) : $signed(v);
endmodule
